import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import AdminSidebar from '../../components/AdminSidebar';
import toast from 'react-hot-toast';
import './AdminUsersPage.css';

const AdminUsersPage = () => {
  const { user, api } = useAuth();
  const navigate = useNavigate();
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [showVerifyModal, setShowVerifyModal] = useState(false);
  const [selectedUser, setSelectedUser] = useState(null);
  const [adminNotes, setAdminNotes] = useState('');

  useEffect(() => {
    if (!user || user.role !== 'admin') {
      navigate('/admin/login');
      return;
    }
    fetchUsers();
  }, [user, navigate]);

  const fetchUsers = async () => {
    try {
      const response = await api.get('/admin/users');
      setUsers(response.data);
    } catch (error) {
      console.error('Error fetching users:', error);
      toast.error('Failed to load users');
    } finally {
      setLoading(false);
    }
  };

  const handleVerify = async (approved) => {
    if (!selectedUser) return;

    try {
      const status = approved ? 'approved' : 'rejected';
      await api.put(`/admin/users/${selectedUser._id}/verify`, {
        isVerified: approved,
        verificationStatus: status,
        verificationNotes: adminNotes
      });

      toast.success(approved ? 'User verified successfully!' : 'User rejected');
      fetchUsers();
      setShowVerifyModal(false);
      setSelectedUser(null);
      setAdminNotes('');
    } catch (error) {
      toast.error('Failed to verify user');
    }
  };

  const handleSuspend = async (userId, currentStatus) => {
    if (window.confirm(`Are you sure you want to ${currentStatus ? 'unsuspend' : 'suspend'} this user?`)) {
      try {
        await api.put(`/admin/users/${userId}/suspend`);
        toast.success(`User ${currentStatus ? 'unsuspended' : 'suspended'} successfully`);
        fetchUsers();
      } catch (error) {
        toast.error('Operation failed');
      }
    }
  };

  const openVerifyModal = (userData) => {
    setSelectedUser(userData);
    setAdminNotes('');
    setShowVerifyModal(true);
  };

  const getVerificationBadge = (userData) => {
    if (userData.verificationStatus === 'approved') {
      return <span className="badge badge-verified"><i className="fas fa-check-circle"></i> VERIFIED</span>;
    } else if (userData.verificationStatus === 'rejected') {
      return <span className="badge badge-rejected"><i className="fas fa-times-circle"></i> REJECTED</span>;
    } else {
      return <span className="badge badge-pending"><i className="fas fa-clock"></i> PENDING</span>;
    }
  };

  const filteredUsers = users.filter(u => {
    if (searchTerm && !u.fullName.toLowerCase().includes(searchTerm.toLowerCase()) && 
        !u.email.toLowerCase().includes(searchTerm.toLowerCase())) {
      return false;
    }
    return true;
  });

  const sortedUsers = [...filteredUsers].sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));

  if (loading) {
    return (
      <div className="admin-users-wrapper">
        <AdminSidebar />
        <div className="admin-users-content" style={{ textAlign: 'center', paddingTop: '50px' }}>
          Loading users...
        </div>
      </div>
    );
  }

  return (
    <div className="admin-users-wrapper">
      <AdminSidebar />
      <div className="admin-users-content">
        <h1 style={{ fontSize: '2rem', background: 'linear-gradient(135deg, #AD8878, #6EA094)', WebkitBackgroundClip: 'text', color: 'transparent', marginBottom: '1rem' }}>
          <i className="fas fa-users"></i> MANAGE USERS
        </h1>

        <div className="stats-container">
          <div className="stat-item">
            <i className="fas fa-users"></i> Total: {users.length}
          </div>
          <div className="stat-item pending">
            <i className="fas fa-clock"></i> Pending: {users.filter(u => u.verificationStatus === 'pending').length}
          </div>
          <div className="stat-item verified">
            <i className="fas fa-check-circle"></i> Verified: {users.filter(u => u.verificationStatus === 'approved').length}
          </div>
        </div>

        <div style={{ marginBottom: '2rem', marginTop: '1rem' }}>
          <input
            type="text"
            className="search-input"
            placeholder="Search by name or email..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>

        <div className="users-table-container">
          <table className="users-table">
            <thead>
              <tr>
                <th className="user-cell">User</th>
                <th className="contact-cell">Contact</th>
                <th className="date-cell">Registered</th>
                <th className="verification-cell">Verification</th>
                <th className="status-cell">Status</th>
                <th className="actions-cell">Actions</th>
              </tr>
            </thead>
            <tbody>
              {sortedUsers.map(u => (
                <tr key={u._id} style={{ background: u.verificationStatus === 'pending' ? 'rgba(255, 242, 235, 0.3)' : 'white' }}>
                  <td>
                    <div>
                      <div style={{ fontWeight: '600', color: '#5E4B3F' }}>{u.fullName}</div>
                      <div style={{ fontSize: '0.75rem', color: '#A98978', marginTop: '4px' }}>{u.email}</div>
                    </div>
                  </td>
                  <td>{u.contact}</td>
                  <td style={{ fontSize: '13px' }}>{new Date(u.createdAt).toLocaleDateString()}</td>
                  <td>{getVerificationBadge(u)}</td>
                  <td>
                    <span className={u.isSuspended ? 'status-suspended' : 'status-active'}>
                      {u.isSuspended ? 'SUSPENDED' : 'ACTIVE'}
                    </span>
                  </td>
                  <td>
                    {u.verificationStatus === 'pending' && (
                      <button className="verify-btn" onClick={() => openVerifyModal(u)}>
                        <i className="fas fa-id-card"></i> Verify
                      </button>
                    )}
                    <button className="suspend-btn" onClick={() => handleSuspend(u._id, u.isSuspended)}>
                      <i className={`fas ${u.isSuspended ? 'fa-user-check' : 'fa-ban'}`}></i>
                      {u.isSuspended ? ' Unsuspend' : ' Suspend'}
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Verify Modal */}
      {showVerifyModal && selectedUser && (
        <div className="modal-overlay active" onClick={() => setShowVerifyModal(false)}>
          <div className="modal-container" onClick={(e) => e.stopPropagation()}>
            <i className="fas fa-times modal-close" onClick={() => setShowVerifyModal(false)}></i>
            <h2><i className="fas fa-id-card"></i> Verify User</h2>

            <div className="user-details">
              <div className="detail-row">
                <span className="detail-label">Full Name:</span>
                <span className="detail-value">{selectedUser.fullName}</span>
              </div>
              <div className="detail-row">
                <span className="detail-label">Email:</span>
                <span className="detail-value">{selectedUser.email}</span>
              </div>
              <div className="detail-row">
                <span className="detail-label">Contact:</span>
                <span className="detail-value">{selectedUser.contact}</span>
              </div>
              <div className="detail-row">
                <span className="detail-label">Registered:</span>
                <span className="detail-value">{new Date(selectedUser.createdAt).toLocaleString()}</span>
              </div>
            </div>

            <div className="id-preview">
              <i className="fas fa-id-card"></i>
              <p><strong>Uploaded ID:</strong> {selectedUser.idFileName || 'No ID uploaded'}</p>
              {selectedUser.idImageData && (
                <img src={selectedUser.idImageData} alt="User ID" />
              )}
            </div>

            <div className="admin-notes">
              <label>Admin Notes</label>
              <textarea
                rows="3"
                value={adminNotes}
                onChange={(e) => setAdminNotes(e.target.value)}
                placeholder="Add notes about this verification..."
              />
            </div>

            <div className="modal-actions">
              <button className="approve-btn" onClick={() => handleVerify(true)}>
                <i className="fas fa-check-circle"></i> Approve User
              </button>
              <button className="reject-btn" onClick={() => handleVerify(false)}>
                <i className="fas fa-times-circle"></i> Reject User
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminUsersPage;
